import { Link } from "react-router-dom";
import { useEffect,useState } from "react";
import axios from 'axios'
import Teachersidebar from "./Teachersidebar";
import { useParams } from "react-router-dom";
import {swal} from 'sweetalert2';
const baseUrl="http://127.0.0.1:8000/api/course-chapters/4"
function CourseChapters(){
    const[chapterData,setChapterData]=useState([]);
    const[totalResult,setTotalResult]=useState(0);
    const {course_id}=useParams();

    useEffect(()=>{
        try{
            axios.get(baseUrl+'/course-chapters/'+course_id).then((res)=>{
                setChapterData(res.data)
                setTotalResult(res.data.length)
            });
        }catch(error){
            console.log(error)
        }
    },[])
    const handleDeleteClick=()=>{
        swal({
            title:"Are you sure?",
            text:"Once deleted, you will not be able to recover this file!",    
            icon:"warning",
            buttons:true,
            dangerMode:true,    
        }).then((willDelete)=>{
            if(willDelete){
                swal("Your file has been deleted!",{    
                    icon:"success",
                });
            }else{
                swal("Your file is safe!");
            }   
        });
    }
    return(
        <div className="container mt-4">
            <div className="row">
                <aside className="col-md-3">
                    <Teachersidebar></Teachersidebar>
                </aside>
                <section className="col-md-9">
                    <div className="card">
                        <h5 className="card-header">All Chapter({totalResult})</h5>
                        <div className="card-body">
                            <table className="table table-bordered">
                        <thead>
                            <tr>
                                <th>Title</th>
                                <th>Vidio</th>
                                <th>Remarks</th>
                                <th>Action</th>
                            </tr>
                        </thead>
                        <tbody>
                            {chapterData.map((Chapter,index)=>(
                                <tr className="px-2 py-2" key={index}>
                                    <td><Link to={'/delete-chapter/'+Chapter.id}>{Chapter.title}</Link></td>
                                    <td>
                                    <video width="320" height="240" controls>
                                    <source src={Chapter.video.url} type="video/mp4"/>
                                    <source src={Chapter.video.url} type="video/ogg"/>
                                    Your browser does not support the video tag.
                                    </video></td>
                                    <td>{Chapter.remarks}</td>
                                    <td>
                                        <Link to={'/edit-chapter/'+Chapter.id} className="btn btn-sm btn-info mx-2">Edit</Link>   
                                        <button onClick={handleDeleteClick} className="btn btn-sm btn-danger mx-2">Delete</button>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                        </div>
                    </div>
                </section>
            </div>
        </div>
    )
}
export default CourseChapters
